```c++
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    // Abrir el archivo de texto
    string fileName;
    cout << "Introduzca el nombre del archivo de texto: ";
    cin >> fileName;

    ifstream inputFile(fileName);

    // Verificar si el archivo se abrió correctamente
    if (!inputFile.is_open()) {
        cerr << "Error: No se pudo abrir el archivo " << fileName << endl;
        return 1;
    }

    // Palabra a buscar
    string searchWord;
    cout << "Introduzca la palabra a buscar: ";
    cin >> searchWord;

    // Contador para el número de apariciones
    int count = 0;

    // Leer línea por línea del archivo
    string line;
    while (getline(inputFile, line)) {
        // Separar las palabras de la línea actual
        size_t pos = 0;
        string token;
        while ((pos = line.find(" ")) != string::npos) {
            token = line.substr(pos, pos + 1 - pos);
            line.erase(pos, pos + 1);
        }
        token = line;

        // Contar las apariciones de la palabra a buscar
        size_t found = line.find(searchWord);
        while (found != string::npos) {
            count++;
            found = line.find(searchWord, found + 1);
        }
    }

    // Mostrar el resultado
    cout << "El número de apariciones de \"" << searchWord << "\" en " << fileName << " es: " << count << endl;

    // Cerrar el archivo de texto
    inputFile.close();

    return 0;
}
```

